func (t *SMTPSetup) Init() {
	t.Enabled = *new(bool)
	t.Smtp_server = *new(types.Text)
	t.Smtp_server_port = *new(int)
	t.User_id = *new(types.Text)
	t.Password = *new(types.Text)
	t.From_address = *new(types.Text)
	t.applyDefaults()
}

